import React, { useEffect, useState } from "react";
import { useParams } from "react-router-dom";
import axios from "axios";

const CandidateDetail = () => {
  const { id } = useParams();
  const [candidate, setCandidate] = useState(null);

  useEffect(() => {
    axios
      .get(`http://localhost:5000/results/${id}`)
      .then((res) => setCandidate(res.data))
      .catch(() => setCandidate(null));
  }, [id]);

  if (!candidate) {
    return <p className="m-4 text-danger">Candidate not found</p>;
  }

  return (
    <div className="container mt-4">
      <h3>{candidate.filename}</h3>

      <p>
        <strong>Final Score:</strong> {candidate.final_score}%
      </p>
      <p>
        <strong>Status:</strong> {candidate.decision}
      </p>

      <hr />

      <h5>Mandatory Skills</h5>
      <p>Status: {candidate.rules.mandatory_skills.status}</p>

      {candidate.rules.mandatory_skills.missing.length > 0 && (
        <ul>
          {candidate.rules.mandatory_skills.missing.map((s, i) => (
            <li key={i}>{s}</li>
          ))}
        </ul>
      )}

      <hr />

      <h5>Skill Match</h5>
      <p>Match Score: {candidate.rules.skill_overlap.score}%</p>
      <p>Matched Skills:</p>
      <ul>
        {candidate.rules.skill_overlap.matched.map((s, i) => (
          <li key={i}>{s}</li>
        ))}
      </ul>

      <hr />

      <h5>GitHub</h5>
      <p>{candidate.rules.github.evidence}</p>

      <hr />

      <h5>AI Insights (Coming Next)</h5>
      <p className="text-muted">
        JD‑conditioned strengths and red flags will appear here.
      </p>
    </div>
  );
};

export default CandidateDetail;
